const clean=list=>list.filter(x=>!String(x.url||'').startsWith('data:'));
async function newPage(browser,w,h){const page=await browser.newPage();await page.setViewport({width:w,height:h,deviceScaleFactor:1});page.setDefaultNavigationTimeout(18000);page.setDefaultTimeout(8000);const e={consoleErrors:[],pageErrors:[],requestFailures:[],badResponses:[]};page.on('console',m=>{if(m.type()==='error')e.consoleErrors.push(m.text())});page.on('pageerror',x=>e.pageErrors.push(String(x)));page.on('requestfailed',r=>e.requestFailures.push({url:r.url(),error:r.failure()?.errorText||'failed'}));page.on('response',r=>{if(r.status()>=400)e.badResponses.push({url:r.url(),status:r.status()})});return{page,e}}
async function goto(page,route){const r=await page.goto(BASE+route,{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>document.readyState==='complete',{timeout:8000}).catch(()=>{});await sleep(180);return r?.status()||0}
async function capture(page,selector,file,maxH=1200){const b=await page.$eval(selector,e=>{const r=e.getBoundingClientRect();return{x:0,y:Math.max(0,r.top+window.scrollY),width:document.documentElement.clientWidth,height:r.height}});const clip={x:0,y:b.y,width:b.width,height:Math.max(1,Math.min(b.height,maxH))};await page.screenshot({path:file,clip,captureBeyondViewport:true});return clip}
async function checkExternal(){
 const routes=[
  ['https://evidenceaxis.com','Find what your competitive view is missing.'],
  ['https://evidenceaxis.com/sample-report/','Demonstration sample'],
  ['https://evidenceaxis.com/work/','Proof that the research can carry into real decisions.'],
  ['https://evidenceaxis.com/contact/','Put Evidence Axis on your competitive question.']
 ];
 for(const [url,marker] of routes){const scope='external-'+url;try{const res=await fetch(url,{redirect:'follow',headers:{'user-agent':'Mozilla/5.0 Phase14QA'}});const body=await res.text();const rec={url,status:res.status,finalUrl:res.url,marker,markerFound:body.includes(marker),bytes:body.length};report.externalRoutes.push(rec);ok(res.status>=200&&res.status<400,scope,'external route status not successful',rec);ok(body.includes(marker),scope,'external route did not return intended page marker',rec)}catch(err){report.externalRoutes.push({url,error:String(err)});ok(false,scope,'external route fetch failed',{error:String(err)})}}
}
(async()=>{
 await checkExternal();
 const browser=await puppeteer.launch({executablePath:CHROME,headless:'new',args:['--no-sandbox','--disable-dev-shm-usage']});
 try{
  for(const [label,w,h] of viewports){
   const {page,e}=await newPage(browser,w,h);const status=await goto(page,'evidence-axis.html');
   const data=await page.evaluate(()=>{
    const r=e=>{const x=e.getBoundingClientRect();return{x:x.x,y:x.y,left:x.left,top:x.top,right:x.right,bottom:x.bottom,width:x.width,height:x.height}};
    const main=document.querySelector('main');const h1=main.querySelector('h1');const intro=main.querySelector('.axis-bridge-hero .intro');const actions=[...main.querySelectorAll('.axis-hero-actions a')];const ext=[...main.querySelectorAll('a[href^="https://evidenceaxis.com"]')];const footer=document.querySelector('footer.site-footer');
    return{h1Count:main.querySelectorAll('h1').length,h1:h1?.innerText.replace(/\s+/g,' ').trim()||'',h1Rect:h1?r(h1):null,statusText:main.querySelector('.axis-venture-status')?.textContent.trim()||'',intro:intro?.textContent.trim()||'',introRect:intro?r(intro):null,actions:actions.map(a=>({text:a.textContent.trim(),href:a.getAttribute('href'),rect:r(a)})),sections:['what-it-does','research-discipline','public-proof','portfolio-relationship','continue'].map(id=>({id,exists:!!document.getElementById(id),rect:document.getElementById(id)?r(document.getElementById(id)):null})),relationship:document.querySelector('#portfolio-relationship .section-cap p')?.textContent.trim()||'',proof:document.querySelector('#public-proof')?.innerText||'',external:ext.map(a=>({href:a.getAttribute('href'),target:a.getAttribute('target'),rel:a.getAttribute('rel')||'',text:a.textContent.trim()})),heroBg:getComputedStyle(document.querySelector('.axis-bridge-hero'),'::before').backgroundImage,imgCount:main.querySelectorAll('img').length,scrollWidth:document.documentElement.scrollWidth,innerWidth:window.innerWidth,duplicateIds:(()=>{const a=[...document.querySelectorAll('[id]')].map(x=>x.id);return[...new Set(a.filter((id,i)=>a.indexOf(id)!==i))]})(),footerTop:footer?r(footer).top:null,mainBottom:r(main).bottom,clipTexts:[...main.querySelectorAll('h2,h3,.axis-venture-status,.axis-focus-grid article>span,.axis-handoff-card>span')].map(x=>({text:x.textContent.trim(),scrollWidth:x.scrollWidth,clientWidth:x.clientWidth,left:r(x).left,right:r(x).right}))};
   });
   const scope='axis-'+label;ok([200,304].includes(status),scope,'HTTP status',{status});ok(data.h1Count===1,scope,'exactly one H1 required',{h1Count:data.h1Count});ok(data.h1==='Evidence Axis.',scope,'H1 identity mismatch',{h1:data.h1});ok(data.statusText==='SPECIALIST VENTURE',scope,'specialist venture status missing',{status:data.statusText});ok(/Competitive intelligence for B2B SaaS decisions/i.test(data.intro),scope,'current specialist positioning missing',{intro:data.intro});ok(data.h1Rect&&data.h1Rect.top<h&&data.h1Rect.bottom<=h+2,scope,'H1 not in first viewport',{rect:data.h1Rect,height:h});ok(data.introRect&&data.introRect.top<h,scope,'core positioning does not begin in first viewport',{rect:data.introRect,height:h});ok(data.actions.length===2,scope,'hero must expose exactly two primary paths',{actions:data.actions});for(const a of data.actions)ok(a.rect.top<h&&a.rect.bottom<=h+2,scope,'hero CTA not fully visible in first viewport',{cta:a,height:h});ok(data.actions.some(a=>a.href==='https://evidenceaxis.com/sample-report/'&&/View Public Sample/i.test(a.text)),scope,'direct public sample CTA missing',{actions:data.actions});ok(data.actions.some(a=>a.href==='https://evidenceaxis.com'&&/Open EvidenceAxis\.com/i.test(a.text)),scope,'specialist-site CTA missing',{actions:data.actions});for(const s of data.sections)ok(s.exists,scope,'required bridge section missing',{section:s.id});ok(data.relationship==='Evidence Axis is a specialist venture within the Unique Holding portfolio.',scope,'locked relationship wording mismatch',{relationship:data.relationship});ok(/Demonstration sample — not a client engagement\./.test(data.proof),scope,'public sample client-boundary disclosure missing');ok(/subjects of public competitive analysis, not customers, partners or endorsers/i.test(data.proof),scope,'sample subject relationship boundary missing');ok(!/url\(/i.test(data.heroBg),scope,'remote/image hero background returned',{heroBg:data.heroBg});ok(data.imgCount===0,scope,'unexpected image/screenshot published',{imgCount:data.imgCount});for(const a of data.external){ok(a.target==='_blank',scope,'external Evidence Axis target missing',{link:a});ok(a.rel.split(/\s+/).includes('noopener'),scope,'external Evidence Axis noopener missing',{link:a})}ok(data.scrollWidth<=data.innerWidth+1,scope,'horizontal overflow',{scrollWidth:data.scrollWidth,innerWidth:data.innerWidth});ok(data.duplicateIds.length===0,scope,'duplicate IDs',{ids:data.duplicateIds});ok(data.footerTop>=data.mainBottom-2,scope,'footer overlaps main transition',{footerTop:data.footerTop,mainBottom:data.mainBottom});for(const t of data.clipTexts)ok(t.scrollWidth<=t.clientWidth+2&&t.left>=-1&&t.right<=data.innerWidth+1,scope,'heading/label clips',{item:t});ok(e.consoleErrors.length===0,scope,'console errors',{errors:e.consoleErrors});ok(e.pageErrors.length===0,scope,'page errors',{errors:e.pageErrors});ok(clean(e.requestFailures).length===0,scope,'request failures',{errors:e.requestFailures});ok(e.badResponses.length===0,scope,'bad HTTP subresources',{errors:e.badResponses});
   await page.screenshot({path:path.join(SHOTS,'evidence-axis',`evidence-axis-${label}.png`),fullPage:true});
   for(const [name,sel] of [['hero','.axis-bridge-hero'],['public-proof','#public-proof'],['research-discipline','#research-discipline'],['portfolio-relationship','#portfolio-relationship'],['specialist-handoff','#continue']]){const file=path.join(SHOTS,'focus',`${name}-${label}.png`);const clip=await capture(page,sel,file,name==='hero'?Math.min(h,900):1100);report.focusCaptures.push({label,name,file:path.relative(OUT,file),clip})}
   report.axisCases.push({label,status,h1Rect:data.h1Rect,introRect:data.introRect,actions:data.actions,sections:data.sections,relationship:data.relationship,external:data.external,heroBg:data.heroBg,scrollWidth:data.scrollWidth,innerWidth:data.innerWidth,errors:e});
   if(w<=390)report.mobile.push({label,h1Rect:data.h1Rect,introRect:data.introRect,actions:data.actions,clipTexts:data.clipTexts});
   await page.close();
  }

  for(const [label,w,h] of techViewports){
   const {page,e}=await newPage(browser,w,h);const status=await goto(page,'technology.html');const count=await page.$$eval('img[data-tech-visual]',els=>els.length);for(let i=0;i<count;i++){await page.$$eval('img[data-tech-visual]',(els,i)=>els[i].scrollIntoView({block:'center'}),i);await sleep(100);await page.waitForFunction(i=>{const x=document.querySelectorAll('img[data-tech-visual]')[i];return x&&x.complete&&x.naturalWidth>0},{timeout:8000},i)}await page.evaluate(()=>window.scrollTo(0,0));await sleep(120);
   const data=await page.evaluate(()=>({visuals:[...document.querySelectorAll('img[data-tech-visual]')].map(x=>({key:x.dataset.techVisual,src:x.getAttribute('src'),currentSrc:x.currentSrc,naturalWidth:x.naturalWidth,naturalHeight:x.naturalHeight,rect:(()=>{const r=x.getBoundingClientRect();return{left:r.left,right:r.right,width:r.width,height:r.height}})()})),remote:[...performance.getEntriesByType('resource')].map(x=>x.name).filter(x=>/images\.unsplash\.com/i.test(x)),areaCount:document.querySelectorAll('[data-tech-area]').length,body:document.querySelector('main')?.innerText||'',scrollWidth:document.documentElement.scrollWidth,innerWidth:window.innerWidth}));
   const scope='phase13-'+label;ok([200,304].includes(status),scope,'Technology HTTP status',{status});ok(data.visuals.length===5,scope,'Phase 13 five local visuals regression',{visuals:data.visuals});for(const v of data.visuals){ok(v.src.startsWith('assets/phase13/'),scope,'Phase 13 visual path regression',{v});ok(v.naturalWidth>0&&v.naturalHeight>0,scope,'Phase 13 visual failed to load',{v});ok(!/unsplash/i.test(v.currentSrc),scope,'Phase 13 visual resolved remote',{v});ok(v.rect.width>180&&v.rect.height>150,scope,'Phase 13 visual crop collapsed',{v})}ok(data.remote.length===0,scope,'Unsplash request returned on Technology',{remote:data.remote});ok(data.areaCount===4,scope,'Phase 12 operating-area count regression',{areaCount:data.areaCount});ok(data.body.includes('Technology & intelligence for decisions, products and new ventures.'),scope,'Phase 12 content regression');ok(data.scrollWidth<=data.innerWidth+1,scope,'Technology horizontal overflow',{data});ok(e.consoleErrors.length===0&&e.pageErrors.length===0&&clean(e.requestFailures).length===0&&e.badResponses.length===0,scope,'Technology browser errors',{e});await page.screenshot({path:path.join(SHOTS,'phase13',`technology-${label}.png`),fullPage:true});report.phase13.push({label,status,...data,errors:e});await page.close();
  }
 }finally{await browser.close()}
 report.summary={axisCases:report.axisCases.length,mobileCases:report.mobile.length,externalRoutes:report.externalRoutes.length,phase13Cases:report.phase13.length,focusCaptures:report.focusCaptures.length,failures:report.failures.length};fs.writeFileSync(path.join(REPORTS,'phase14-browser-report.json'),JSON.stringify(report,null,2));fs.writeFileSync(path.join(REPORTS,'external-route-report.json'),JSON.stringify(report.externalRoutes,null,2));console.log(JSON.stringify(report.summary,null,2));if(report.failures.length){console.error(JSON.stringify(report.failures,null,2));process.exit(1)}
})().catch(e=>{console.error(e);process.exit(1)});
